import Link from "next/link";
import {AdminNav} from "@/components/admin/admin-nav";
import {requireAdmin} from "@/lib/admin/authorization";
import {getPreferences} from "@/lib/i18n/get-translations";
import {createChallengeAction} from "../actions";
export default async function Page({searchParams}:{searchParams:Promise<{error?:string}>}){const actor=await requireAdmin("CHALLENGE_MANAGE");const p=await getPreferences(actor.id);const vi=p.interfaceLanguage==="vi";const q=await searchParams;return <main className="min-h-screen bg-slate-50 px-4 py-6 sm:px-6"><div className="mx-auto max-w-6xl"><AdminNav locale={p.interfaceLanguage}/><div className="mx-auto mt-8 max-w-2xl"><Link className="text-sm font-bold text-teal-700" href="/admin/challenges">← {vi?"Sự kiện xếp hạng":"Ranking events"}</Link><form action={createChallengeAction} className="mt-4 grid gap-5 rounded-3xl border bg-white p-6 sm:p-8"><h1 className="text-3xl font-black">{vi?"Tạo bản nháp sự kiện":"Create event draft"}</h1><p className="text-slate-600">{vi?"Tạo nháp trước. Sau đó hệ thống lấy đề từ ngân hàng câu hỏi đã xuất bản để bạn kiểm tra và công bố. Mỗi người học chỉ có một lượt làm; điểm là số câu đúng, không phải RP của bảng tuần.":"Create a draft, generate a test from published questions, review it, then publish. Each learner gets one attempt, scored by correct answers rather than weekly RP."}</p>{q.error&&<p role="alert" className="rounded-xl bg-amber-50 p-3">{vi?"Không thể tạo sự kiện. Kiểm tra thời gian, tiêu đề và loại đề.":"Could not create the event. Check the dates, titles, and test type."}</p>}<fieldset className="grid gap-3"><legend className="mb-3 text-lg font-bold">{vi?"1. Thông tin hiển thị":"1. Display information"}</legend><label className="font-semibold">Tiêu đề tiếng Việt<input className="mt-1 w-full rounded-lg border p-3" name="titleVi" required maxLength={160}/></label><label className="font-semibold">English title<input className="mt-1 w-full rounded-lg border p-3" name="titleEn" required maxLength={160}/></label></fieldset><fieldset className="grid gap-3"><legend className="mb-3 text-lg font-bold">{vi?"2. Đề thi và cách chấm":"2. Test and scoring"}</legend><label className="font-semibold">{vi?"Loại đề":"Test type"}<select className="mt-1 w-full rounded-lg border p-3" name="type"><option value="READING_100">Reading · 100 câu · 75 phút</option><option value="LISTENING_100">Listening · 100 câu · 45 phút</option><option value="FULL_200">Listening và Reading · 200 câu · 120 phút</option></select></label><p className="text-sm text-slate-600">{vi?"Điểm sự kiện là số câu đúng. Đề được tạo tự động từ nội dung đủ điều kiện; không có bộ lọc Part tùy chỉnh.":"Event score is the number of correct answers. The test is generated from eligible content; custom Part filters are unavailable."}</p></fieldset><fieldset className="grid gap-3"><legend className="mb-3 text-lg font-bold">{vi?"3. Lịch (giờ Việt Nam, GMT+7)":"3. Schedule (Vietnam time, GMT+7)"}</legend><label className="font-semibold">{vi?"Bắt đầu":"Start"}<input className="mt-1 w-full rounded-lg border p-3" name="startsAt" required type="datetime-local"/></label><label className="font-semibold">{vi?"Kết thúc":"End"}<input className="mt-1 w-full rounded-lg border p-3" name="endsAt" required type="datetime-local"/></label><p className="text-sm text-slate-600">{vi?"Khoảng thời gian phải đủ dài để hoàn thành loại đề đã chọn. Công bố trước giờ bắt đầu để người học thấy sự kiện sắp diễn ra.":"The window must allow enough time to finish the selected test. Publish before the start time so learners can see the upcoming event."}</p></fieldset><button className="min-h-12 rounded-xl bg-slate-900 px-5 font-bold text-white">{vi?"Lưu bản nháp":"Save draft"}</button></form></div></div></main>}
